import Foundation
@testable import ColorComposerCore

/// Decodable mirror of the `color_matching` solver parity corpus
/// (`priv/parity/v1/corpus.json` in viamin/color_matching, tracked upstream by
/// issue #111). The corpus is generated by the Elixir `WeightedSquaredError`
/// solver and vendored verbatim at `Fixtures/parity/v1/corpus.json` so this
/// client's scorer can be replayed against it for parity.
struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let lightSources: [String]
    let missingPolicy: String
    let scorer: String
    let selection: String
    let scenarios: [ParityScenario]
}

struct ParityScenario: Decodable {
    let id: String
    let description: String
    let palette: [ParityColor]
    let target: ParityColor
    let weights: [String: Double]
    let expected: ParityExpectation
}

/// One palette entry or the scenario target. `channels` omits a light source
/// entirely when unmeasured — never a zero — matching the exclusion policy
/// `WeightedSquaredErrorScorer` enforces.
struct ParityColor: Decodable {
    let index: Int?
    let hexColor: String?
    let channels: [String: Double]
}

struct ParityExpectation: Decodable {
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]
    let scores: [ParityScoreEntry]
}

struct ParityScoreEntry: Decodable {
    let index: Int
    let score: ParityScoreValue
}

/// The corpus encodes an excluded candidate's score as the string
/// `"excluded"` rather than a number.
enum ParityScoreValue: Decodable {
    case value(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
            return
        }
        let string = try container.decode(String.self)
        guard string == "excluded" else {
            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "Expected a number or \"excluded\", found \"\(string)\""
            )
        }
        self = .excluded
    }
}

extension ParityCorpus {
    /// Loads the vendored corpus fixture next to this source file.
    static func loadFixture(file: StaticString = #filePath) -> ParityCorpus {
        let fixtureURL = URL(fileURLWithPath: "\(file)")
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/parity/v1/corpus.json")
        let data: Data
        do {
            data = try Data(contentsOf: fixtureURL)
        } catch {
            fatalError("Could not read parity corpus fixture at \(fixtureURL.path): \(error)")
        }
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        do {
            return try decoder.decode(ParityCorpus.self, from: data)
        } catch {
            fatalError("Could not decode parity corpus fixture: \(error)")
        }
    }
}

extension ParityScenario {
    /// Converts the scenario's declared weights into `ChannelWeights`,
    /// ignoring keys this client's `LightingCondition` does not recognize
    /// (the corpus includes an `unknown-weight-ignored` scenario exercising
    /// exactly this).
    var channelWeights: ChannelWeights {
        func weight(for condition: LightingCondition) -> Double {
            weights[condition.rawValue] ?? 0
        }
        return ChannelWeights(
            white: weight(for: .white),
            red: weight(for: .red),
            green: weight(for: .green),
            blue: weight(for: .blue),
            lps: weight(for: .lps)
        )
    }

    var targetVector: TargetResponseVector {
        TargetResponseVector(target.brightnessByCondition)
    }

    var paletteColors: [PaletteColor] {
        palette.map { $0.asPaletteColor }
    }
}

private extension ParityColor {
    /// `channels` keyed by this client's `LightingCondition`, dropping any
    /// light source it does not recognize.
    var brightnessByCondition: [LightingCondition: Double] {
        var result: [LightingCondition: Double] = [:]
        for (key, value) in channels {
            if let condition = LightingCondition(rawValue: key) {
                result[condition] = value
            }
        }
        return result
    }

    var asPaletteColor: PaletteColor {
        let hex = hexColor ?? "#000000"
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (condition, brightness) in brightnessByCondition {
            responses[condition] = IlluminationResponse(brightness: brightness)
        }
        return PaletteColor(
            id: index ?? 0,
            hex: hex,
            rgb: RGBColor(hex: hex) ?? RGBColor(red: 0, green: 0, blue: 0),
            responses: responses
        )
    }
}
